[DataEventHandler(tableStr(InventInventoryMovementJournalEntryV4Entity), DataEventType::MappedEntityToDataSource)]
public static void InventInventoryMovementJournalEntryV4Entity_onMappedEntityToDataSource(Common _sender, DataEventArgs _eventArgs)
{
    DataEntityContextEventArgs contextEventArgs = _eventArgs as DataEntityContextEventArgs;
    DataEntityRuntimeContext entityCtx = contextEventArgs.parmEntityContext();
    DataEntityDataSourceRuntimeContext dataSourceCtx = contextEventArgs.parmEntityDataSourceContext();

    if ((entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert || entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Update)
        && dataSourceCtx.name() == dataEntityDataSourceStr(TAMRebateAndDeductionsPostingProfileEntity, TAMRebatePosting))
    {
        InventInventoryMovementJournalEntryV4Entity inventInventoryMovementJournalEntry = _sender as InventInventoryMovementJournalEntryV4Entity;
        InventJournalTrans inventJournalTrans = dataSourceCtx.getBuffer();
        if (inventJournalTrans.inventJournalTable().inventJournalName().METExternalWMSUOM)
        {
            if (inventJournalTrans.PdsCWQty)
            {
                inventJournalTrans.PdsCWQty = METJournalUnitConversion::construct().getConvertedQtyCWQtyForItem(InventLocation::find(InventDim::find(inventJournalTrans.InventDimId).InventLocationId),inventJournalTrans.ItemId, inventJournalTrans.PdsCWQty);
            }
            else
            {
                inventJournalTrans.Qty = METJournalUnitConversion::construct().getConvertedQtyCWQtyForItem(InventLocation::find(InventDim::find(inventJournalTrans.InventDimId).InventLocationId),inventJournalTrans.ItemId, inventJournalTrans.Qty);
            }
        }
    }
}
